import {roles,fullyApproved} from './academic-domain.mjs';
import {roleOptions,profileCard,categoriesMarkup,categoryDialog,posterDialog,postersMarkup,evaluationDialog,reportMarkup} from './academic-ui.mjs';
import {celebrate} from './celebration.mjs?v=academic-3';
import {prepareCover} from './cover-upload.mjs';
import {partnerHeader,partnerFooter} from './partners.mjs?v=academic-3';
import {sectionsFor,appearanceFor,designerControls} from './form-design.mjs?v=academic-3';
import {config} from './config.mjs';
import {enhanceView,setWorking} from './motion.mjs';
import {init,currentUser,login,logout,resetPassword,call,demo,resetDemo,completeEmailAccess,isEmailAccess,completeActivation,setAccountPassword} from './api.mjs?v=academic-3';
import {visibleQuestions,validateAnswers,attendanceGate} from './domain.mjs?v=academic-3';
const $=(s,el=document)=>el.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const status={pending:'En espera',approved:'Aprobado',rejected:'No aprobado',processing:'Procesando',done:'Completado',error:'Error',demo:'Simulado',queued:'En cola',ready:'Listo',review:'Revisar envío'};
const badge=v=>`<span class="badge ${esc(v)}">${esc(status[v]||v)}</span>`;
const date=(v,opts={dateStyle:'medium',timeStyle:'short'})=>v?new Intl.DateTimeFormat('es-CO',{timeZone:'America/Bogota',...opts}).format(new Date(v)):'—';
let user,view='overview',selected='',events=[],registrations=[],conferences=[],attendance=[],jobs=[],settings={},draft=null,answers={},step=1,preview=false;
let timer,coverUploading=false,accounts=[],categories=[],posters=[],myProfile={},speakerConferences=[],enrollmentProfile={};
function notice(msg){$('#notice').textContent=msg;$('#notice').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#notice').classList.remove('show'),6500)}
function modal(html){$('#dialog').innerHTML=`<button class="subtle close" data-close aria-label="Cerrar">✕</button>${html}`;$('#dialog').showModal();}
function close(){$('#dialog').close()}
const nav=[['overview','Resumen'],['forms','Formularios'],['registrations','Inscripciones'],['conferences','Conferencias'],['posters','Pósteres y evaluación'],['accounts','Cuentas y roles'],['reports','Reportes'],['settings','Configuración']];
function shell(content,publicMode=false){
 $('#app').innerHTML=`${partnerHeader()}<header class="top"><a class="brand" href="#" style="text-decoration:none"><span class="logo">↗</span><span class="brand-name">${esc(config.brand)}<span style="color:var(--muted)"> / EVENTOS</span></span></a><div class="top-right"><span class="mono">${esc(user?.email||'ACCESO PÚBLICO')}</span>${user?.admin?'<button data-action="admin-home">Administración</button>':''}${user?`<button data-action="portal">${user.admin?'Ver participante':'Mi espacio académico'}</button><button class="subtle" data-action="logout">Salir</button>`:`<button data-action="auth">Ingresar</button>`}${demo?'<button class="subtle" data-action="role">Cambiar rol</button>':''}</div></header>${demo?'<div class="demo"><span><strong>DEMOSTRACIÓN LOCAL</strong> · Datos de ejemplo guardados en este navegador. Los pagos, correos, Drive y certificados no están conectados.</span><button class="subtle" data-action="reset">Reiniciar demo</button></div>':''}${publicMode?`<main id="content" class="public">${content}${partnerFooter()}</main>`:`<div class="shell"><nav class="sidebar" aria-label="Administración"><span class="eyebrow">Espacio de trabajo</span>${nav.map(([v,n],i)=>`<button data-nav="${v}" class="${view===v?'active':''}"><span class="navnum">0${i+1}</span>${n}</button>`).join('')}<div class="foot">CADA PASO, EN ORDEN.<br>Inscripción → asistencia<br><br><span class="good">●</span> ${demo?'Entorno de demostración':'Firebase conectado'}</div></nav><main id="content"><div class="breadcrumb mono">ADMINISTRACIÓN / ${esc(nav.find(n=>n[0]===view)?.[1].toString()||'FORMULARIO')}</div>${content}${partnerFooter()}</main></div>`}`;
 enhanceView();
}
const heading=(title,description,actions='')=>`<div class="heading"><div><span class="eyebrow">Control del evento</span><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;
function eventSelect(){return `<label>Evento<select id="event-select">${events.map(e=>`<option value="${esc(e.id)}" ${selected===e.id?'selected':''}>${esc(e.title)}</option>`).join('')}</select></label>`}
async function loadAdmin(){events=await call('listEvents');if(!events.some(e=>e.id===selected))selected=events[0]?.id||'';registrations=await call('listRegistrations',selected?{eventId:selected}:{});}
function renderOverview(){const approved=registrations.filter(r=>r.status==='approved').length,paid=registrations.filter(r=>r.payment==='approved').length;
 shell(heading('Todo empieza con una conexión.','Diseña la inscripción. Acompaña a cada persona hasta el evento.','<button class="primary" data-action="new-form">＋ Crear formulario</button>')+`<div class="stats">${[['Inscripciones',registrations.length,'Personas registradas'],['En espera',registrations.filter(r=>r.status==='pending').length,'Pendientes de revisión'],['Aprobadas',approved,'Listas para el siguiente paso'],['Pagos aprobados',paid,'Acceso a las conferencias']].map(([t,n,s])=>`<article><span class="eyebrow">${t}</span><strong>${n.toString().padStart(2,'0')}</strong><small>${s}</small></article>`).join('')}</div><div class="split"><section class="panel light"><span class="eyebrow">El recorrido del participante</span><h2>Un evento. Cuatro momentos.</h2><p>Un proceso claro, desde el primer registro hasta el certificado.</p><div class="flow">${[['01','Inscripción','Formulario a tu medida'],['02','Revisión','Aprobación del equipo'],['03','Pago','Validación del pago'],['04','Asistencia','Evidencia y certificado']].map(([n,t,s])=>`<article><span class="num">${n} ↗</span><h3>${t}</h3><small>${s}</small></article>`).join('')}</div><button data-nav="forms">Abrir formularios ↗</button></section><section class="panel"><span class="eyebrow">Formularios</span><h2>La próxima experiencia.</h2>${events.length?events.slice(0,3).map(e=>`<div class="row"><div><h3>${esc(e.title)}</h3><p>${e.questions.length} preguntas · ${e.published?'Publicado':'Borrador'}</p></div><button data-edit="${esc(e.id)}">Editar ↗</button></div>`).join(''):'<p>Crea tu primer formulario para comenzar.</p>'}<div class="hint">Cada persona consulta su estado desde su propia cuenta. La siguiente fase se habilita cuando corresponde.</div></section></div><section class="panel"><div class="panel-head"><h2>Últimas inscripciones</h2><button class="subtle" data-nav="registrations">Ver todas ↗</button></div>${registrationTable(registrations.slice(0,5),false)}</section>`);
}
function renderForms(){shell(heading('Formularios que se adaptan.','Preguntas, pasos y condiciones para cada recorrido.','<button class="primary" data-action="new-form">＋ Crear formulario</button>')+`<div class="grid">${events.map(e=>`<section class="panel ${e.published?'light':''}"><div class="panel-head"><span class="eyebrow">${e.published?'Publicado / v'+e.version:'Borrador'}</span><span class="mono">${e.questions.length} PREGUNTAS</span></div><h2>${esc(e.title)}</h2><p>${esc(e.description)}</p><small>${esc(e.location||'Ubicación por definir')} · ${esc(e.date||'Fecha por definir')}</small><div class="toolbar"><button data-edit="${esc(e.id)}">Editar</button><button data-preview="${esc(e.id)}">Vista previa</button>${e.published?`<button data-share="${esc(e.id)}">Compartir enlace ↗</button>`:''}</div></section>`).join('')||'<div class="empty">Todavía no has creado formularios.</div>'}</div>`)}
function newForm(){draft={id:'',title:'Nuevo evento',description:'',location:'',date:'',sections:[{step:1,title:'Su perfil',description:'Conozcamos su perfil académico.'}],appearance:{theme:'studio',layout:'cards',cover:'orbital'},questions:[{id:crypto.randomUUID(),label:'Pregunta sin título',type:'text',required:true,step:1}]};view='editor';renderEditor()}
function renderEditor(){shell(heading('Diseña el primer paso.','Las condiciones se evalúan con preguntas anteriores.','<button data-action="save-form">Guardar borrador</button><button class="primary" data-action="publish-form">Publicar formulario ↗</button>')+`<section class="panel light"><span class="eyebrow">Identidad del evento</span><div class="fields"><label class="wide">Título<input id="form-title" maxlength="160" value="${esc(draft.title)}"></label><label class="wide">Descripción<textarea id="form-description" maxlength="3000">${esc(draft.description)}</textarea></label><label>Ubicación<input id="form-location" maxlength="300" value="${esc(draft.location)}"></label><label>Fecha del evento<input id="form-date" type="date" value="${esc(draft.date)}"></label></div></section>${designerControls(draft,esc)}<div class="panel-head"><h2>Preguntas del formulario</h2><button data-action="add-question">＋ Añadir pregunta</button></div>${draft.questions.map((q,i)=>`${i===0||draft.questions[i-1].step!==q.step?`<div class="section-break"><span>Sección ${q.step}</span><h3>${esc(sectionsFor(draft).find(s=>s.step===q.step)?.title)}</h3></div>`:'' }<section class="question" data-question="${esc(q.id)}"><header><span class="eyebrow" style="margin:0">Pregunta ${String(i+1).padStart(2,'0')}</span><div class="actions"><button class="subtle" data-move="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Subir pregunta">↑</button><button class="subtle" data-move="${i}" data-dir="1" ${i===draft.questions.length-1?'disabled':''} aria-label="Bajar pregunta">↓</button><button class="subtle danger" data-remove="${i}" aria-label="Eliminar pregunta">Eliminar</button></div></header><div class="fields"><label class="wide">Título de la pregunta<input data-q="label" maxlength="300" value="${esc(q.label)}"></label><label>Tipo de respuesta<select data-q="type">${Object.entries({text:'Respuesta corta',textarea:'Párrafo',email:'Correo electrónico',number:'Número',date:'Fecha',select:'Lista desplegable',radio:'Una opción',checkbox:'Varias opciones'}).map(([v,n])=>`<option value="${v}" ${q.type===v?'selected':''}>${n}</option>`).join('')}</select></label><label>Sección<select data-q="step">${sectionsFor(draft).map(s=>`<option value="${s.step}" ${s.step===q.step?'selected':''}>${s.step}. ${esc(s.title)}</option>`).join('')}</select></label>${['select','radio','checkbox'].includes(q.type)?`<label class="wide">Opciones · una por línea<textarea data-q="options">${esc(q.options?.join('\n')||'Opción 1\nOpción 2')}</textarea></label>`:''}<label class="check"><input data-q="required" type="checkbox" ${q.required?'checked':''}>Respuesta obligatoria</label></div><div class="condition"><label>Mostrar esta pregunta<select data-q="conditionField"><option value="">Siempre</option>${draft.questions.slice(0,i).map(p=>`<option value="${esc(p.id)}" ${q.condition?.field===p.id?'selected':''}>Cuando: ${esc(p.label)}</option>`).join('')}</select></label>${q.condition?`<div class="fields" style="margin-top:16px"><label>Operador<select data-q="conditionOperator"><option value="eq" ${q.condition.operator==='eq'?'selected':''}>Es igual a / contiene</option><option value="neq" ${q.condition.operator==='neq'?'selected':''}>Es diferente de / no contiene</option></select></label><label>Respuesta esperada<input data-q="conditionValue" value="${esc(q.condition.value)}"></label></div>`:''}</div></section>`).join('')}<div class="actions"><button data-action="add-question">＋ Añadir pregunta</button><button data-action="preview-draft">Vista previa</button></div>`)}
function captureDraft(){if(!draft)return;for(const [id,key] of [['form-title','title'],['form-description','description'],['form-location','location'],['form-date','date']])if($('#'+id))draft[key]=$('#'+id).value;if(document.querySelector('[data-section]'))draft.sections=[...document.querySelectorAll('[data-section]')].map(el=>({step:Number(el.dataset.section),title:$('[data-section-title]',el).value,description:$('[data-section-description]',el).value}));if($('#form-layout'))draft.appearance={...draft.appearance,caption:$('#form-caption')?.value||'Ideas que nos unen',theme:$('[name=form-theme]:checked')?.value||'studio',layout:$('#form-layout').value,cover:$('#form-cover').value};}
async function saveForm(publish=false){if(coverUploading)throw new Error('Espere a que termine la preparación de la imagen de portada.');captureDraft();const e=await call('saveEvent',{event:draft});draft=e;if(publish)await call('publishEvent',{eventId:e.id});await loadAdmin();view='forms';renderForms();notice(publish?'Formulario publicado. Ya puedes compartir el enlace.':'Borrador guardado.');}
function registrationTable(rows,actions=true){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Participante</th><th>Inscripción</th><th>Pago</th><th>Registro</th>${actions?'<th>Acciones</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}<small>${esc(r.email)} · ${esc(roles[r.role]||roles.attendee)}</small></td><td>${badge(r.status)}</td><td>${badge(r.payment)}</td><td><small>${date(r.createdAt)}</small></td>${actions?`<td><div class="actions"><button data-detail="${esc(r.id)}">Ver</button>${r.status==='pending'?`<button data-review="${esc(r.id)}" data-status="approved">Aprobar</button><button class="danger" data-review="${esc(r.id)}" data-status="rejected">No aprobar</button>`:''}${r.status==='approved'&&r.payment!=='approved'?`<button data-payment="${esc(r.id)}">Validar pago</button>`:''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay inscripciones que coincidan.</div>'}
function renderRegistrations(filter='',query=''){const rows=registrations.filter(r=>(!filter||r.status===filter)&&(!query||`${r.name} ${r.email}`.toLowerCase().includes(query.toLowerCase())));shell(heading('Cada persona, un recorrido.','Revisa las respuestas y habilita el siguiente paso.')+`<div class="panel-head">${eventSelect()}<label class="search">Buscar participante<input id="search" value="${esc(query)}" placeholder="Nombre o correo"></label></div><div class="tabs">${[['','Todas'],['pending','En espera'],['approved','Aprobadas'],['rejected','No aprobadas']].map(([v,n])=>`<button data-filter="${v}" aria-pressed="${filter===v}">${n}</button>`).join('')}</div><section class="panel light">${registrationTable(rows)}</section>`);$('#search').oninput=e=>{const v=e.target.value;renderRegistrations(filter,v);$('#search').focus();$('#search').setSelectionRange(v.length,v.length)}}
function renderConferences(){shell(heading('El conocimiento tiene su momento.','Crea conferencias y define cuándo se puede sellar la asistencia.','<button class="primary" data-action="new-conference">＋ Crear conferencia</button>')+`<div class="panel-head">${eventSelect()}<span class="mono">BOGOTÁ · UTC−5</span></div><div class="grid">${conferences.map(c=>conferenceCard(c,true)).join('')||'<div class="empty">Crea una conferencia para este evento.</div>'}</div>`)}
function conferenceCard(c,admin=false,r){const a=attendance.find(a=>a.conferenceId===c.id&&a.registrationId===r?.id);let gate='';if(r)try{attendanceGate(r,c)}catch(e){gate=e.message}return `<section class="panel"><div class="conference"><div class="date"><strong>${date(c.opensAt,{day:'2-digit'})}</strong>${date(c.opensAt,{month:'short'})}</div><div><span class="eyebrow">${c.active?'Conferencia habilitada':'Deshabilitada'}</span><h3>${esc(c.title)}</h3><p>${esc(c.speaker)} · ${esc(c.location)}</p><small>Apertura: ${date(c.opensAt)}<br>Cierre de asistencia: ${date(c.closesAt)} (Bogotá)</small>${a?`<div class="hint">Asistencia sellada: ${date(a.stampedAt)}<br>Certificado: ${esc(status[a.certificateStatus]||a.certificateStatus)}</div>`:gate?`<div class="hint">${esc(gate)}</div>`:''}<div class="actions">${admin?`<button data-conference="${esc(c.id)}">Editar conferencia</button>`:a?`<button data-certificate="${esc(a.id)}" ${a.certificateStatus==='ready'?'':'disabled'}>Descargar certificado ↓</button>`:`<button class="primary" data-stamp="${esc(c.id)}" data-registration="${esc(r?.id)}" ${gate?'disabled':''}>Sellar asistencia ↗</button>`}</div></div></div></section>`}
function conferenceDialog(c={}){if(!selected)return notice('Primero crea un evento.');const local=v=>v?new Date(new Date(v).getTime()-5*3600000).toISOString().slice(0,16):'';modal(`<h2>${c.id?'Editar':'Crear'} conferencia</h2><form id="conference-form" data-id="${esc(c.id||'')}"><div class="fields"><label class="wide">Título<input name="title" required maxlength="200" value="${esc(c.title)}"></label><label class="wide">Vincular ponente aprobado<select name="speakerRegistrationId"><option value="">Sin vínculo</option>${registrations.filter(r=>r.role==='speaker'&&fullyApproved(r)).map(r=>`<option value="${esc(r.id)}" ${c.speakerRegistrationId===r.id?'selected':''}>${esc(r.name)} · ${esc(r.email)}</option>`).join('')}</select></label><label>Ponente<input name="speaker" maxlength="200" value="${esc(c.speaker)}"></label><label>Lugar<input name="location" maxlength="300" value="${esc(c.location)}"></label><label>Abre la asistencia · Bogotá<input name="opensAt" type="datetime-local" required value="${local(c.opensAt)}"></label><label>Cierra la asistencia · Bogotá<input name="closesAt" type="datetime-local" required value="${local(c.closesAt)}"></label><label class="check wide"><input name="active" type="checkbox" ${c.active!==false?'checked':''}>Habilitada</label></div>${c.attendanceCode?`<div class="hint">Clave única: <strong>${esc(c.attendanceCode)}</strong>. Solo el administrador y el ponente vinculado pueden consultarla.</div>`:''}<div class="hint">La fecha y la hora se guardan con zona horaria Bogotá. El servidor verifica el cierre al recibir la evidencia; el reloj del participante no decide.</div><button class="primary">Guardar conferencia</button></form>`)}
function renderReports(){shell(heading('Del registro a la información.','Exporta los registros del evento y consulta los procesos de respaldo.')+`<div class="panel-head">${eventSelect()}<div class="actions"><button class="primary" data-action="export">Inscripciones CSV ↓</button><button data-action="export-attendance">Asistencias CSV ↓</button></div></div><section class="panel light"><h2>Estado de correos y respaldo</h2><p>${demo?'Procesos simulados. No se han enviado correos ni escrito archivos en Drive.':'La cola procesa correos, certificados y respaldo por separado de la inscripción.'}</p><div class="table-wrap"><table><thead><tr><th>Proceso</th><th>Estado</th><th>Fecha</th><th>Detalle</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${esc({registration:'Confirmación de inscripción',status:'Actualización de estado',certificate:'Certificado y correo'}[j.kind]||j.kind)}</td><td>${badge(j.status)}</td><td>${date(j.createdAt)}</td><td>${esc(j.error||'')}${j.status==='error'?`<button data-retry="${esc(j.id)}">Reintentar</button>`:''}${j.status==='review'?'<small>Revisar Gmail antes de volver a enviar.</small>':''}</td></tr>`).join('')}</tbody></table></div>${!jobs.length?'<div class="empty">No hay procesos registrados.</div>':''}</section>`)}
function renderSettings(){shell(heading('Una conexión, cada servicio.','Define la identidad y la organización de las inscripciones.')+`<form id="settings-form" class="panel light"><div class="fields"><label class="wide">Nombre del organizador<input name="organizer" required maxlength="160" value="${esc(settings.organizer)}"></label><label>Correo que recibe copia<input name="ccEmail" type="email" value="${esc(settings.ccEmail)}"></label><label>Etiqueta Gmail<input name="label" maxlength="100" value="${esc(settings.label)}"></label><label class="wide">URL pública de la plataforma<input name="appUrl" type="url" required value="${esc(settings.appUrl)}" placeholder="https://..."></label><label class="wide">URL HTTPS del módulo de pagos existente<input name="paymentUrl" type="url" value="${esc(settings.paymentUrl)}" placeholder="https://..."></label></div><div class="hint">La etiqueta se aplica en el Gmail del organizador. El correo que recibe copia puede crear su propio filtro para usar la misma etiqueta. La URL abre tu módulo; su aprobación requiere integrar una notificación firmada o la validación del administrador.</div><button class="primary">Guardar configuración</button></form><section class="panel"><span class="eyebrow">Conexiones</span><div class="statusline"><span>Firebase · usuarios y registros</span>${badge(demo?'demo':'ready')}</div><div class="statusline"><span>Drive · evidencias y certificados</span><span class="mono">${demo?'PENDIENTE DE CONFIGURAR':'VERIFICAR INSTALACIÓN'}</span></div><div class="statusline"><span>Apps Script · Gmail y Sheets</span><span class="mono">${demo?'PENDIENTE DE CONFIGURAR':'VERIFICAR INSTALACIÓN'}</span></div><div class="hint">Las claves privadas se configuran en el servidor siguiendo la guía incluida. La aplicación pública contiene únicamente la configuración web de Firebase.</div></section>`)}
async function adminView(v){const previousView=view;view=v;await loadAdmin();if(v==='conferences')conferences=selected?await call('listConferences',{eventId:selected}):[];if(v==='reports'){jobs=await call('listJobs',{eventId:selected});attendance=await call('listAttendance',{eventId:selected});}if(v==='settings')settings=await call('getSettings');if(v==='accounts')accounts=await call('listAccounts');if(v==='posters'){accounts=await call('listAccounts');categories=selected?await call('listCategories',{eventId:selected}):[];posters=selected?await call('listPosters',{eventId:selected}):[];}({overview:renderOverview,forms:renderForms,registrations:renderRegistrations,conferences:renderConferences,reports:renderReports,settings:renderSettings,accounts:renderAccounts,posters:renderPosters}[v]||renderOverview)();if(previousView!==v)window.scrollTo({top:0,behavior:'instant'});}
function inputQuestion(q){const v=answers[q.id]??'';return `<div class="form-question"><label for="a-${esc(q.id)}">${esc(q.label)}${q.required?'<span class="required">*</span>':''}</label>${q.type==='textarea'?`<textarea id="a-${esc(q.id)}" data-answer="${esc(q.id)}" maxlength="4000">${esc(v)}</textarea>`:q.type==='select'?`<select id="a-${esc(q.id)}" data-answer="${esc(q.id)}"><option value="">Selecciona una opción</option>${q.options.map(o=>`<option ${v===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:['radio','checkbox'].includes(q.type)?`<div class="choices" role="group" aria-label="${esc(q.label)}">${q.options.map(o=>`<label class="check"><input type="${q.type}" name="${esc(q.id)}" data-answer="${esc(q.id)}" value="${esc(o)}" ${(q.type==='checkbox'?Array.isArray(v)&&v.includes(o):v===o)?'checked':''}>${esc(o)}</label>`).join('')}</div>`:`<input id="a-${esc(q.id)}" type="${q.type}" data-answer="${esc(q.id)}" maxlength="4000" value="${esc(v)}">`}</div>`}
function renderPublic(){const visible=visibleQuestions(draft.questions,answers),sections=sectionsFor(draft),steps=sections.map(s=>s.step),a=appearanceFor(draft);if(!steps.includes(step))step=steps[0];const section=sections.find(s=>s.step===step),index=steps.indexOf(step);shell(`<div class="form-experience layout-${a.layout}" data-theme="${a.theme}">${preview?'<div class="preview-note mono">VISTA PREVIA · NO CREA UNA INSCRIPCIÓN</div>':''}<div class="event-hero cover-${a.cover}"><div class="hero-copy"><span class="event-kicker">Un encuentro para conectar</span><h1>${esc(draft.title)}</h1><p>${esc(draft.description)}</p><div class="event-meta"><span>⌖ ${esc(draft.location||'Ubicación por confirmar')}</span><span>◷ ${esc(draft.date||'Próximamente')}</span><span>${sections.length} ${sections.length===1?'sección':'secciones'}</span></div></div><div class="event-art">${a.cover==='image'&&a.image?`<img class="hero-photo" src="${esc(a.image)}" alt="${esc(a.caption||draft.title)}">`:`<span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="orbit-core" aria-hidden="true">↗</span>`}<span class="art-chip">${esc(a.caption||'Ideas que nos unen')}</span></div></div><div class="form-layout"><aside class="journey-card"><span class="eyebrow">Su recorrido</span><h2>Cada paso nos acerca.</h2><ol>${sections.map((s,i)=>`<li class="${i===index?'current':i<index?'completed':''}" ${i===index?'aria-current="step"':''}><span>${i<index?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${esc(s.title)}</strong><small>${i<index?'Paso completado':i===index?'Se encuentra aquí':'A continuación'}</small></div></li>`).join('')}</ol><div class="journey-note">El comité organizador revisará su inscripción antes de habilitar la siguiente fase.</div></aside><section class="panel light public-card"><div class="form-meter"><span>Inscripción al evento</span><span>Sección ${index+1} de ${steps.length}</span></div><div class="progress form-progress"><i style="width:${(index+1)/steps.length*100}%"></i></div><div class="section-intro"><span class="section-number">${String(index+1).padStart(2,'0')}</span><div><h2>${esc(section.title)}</h2>${section.description?`<p>${esc(section.description)}</p>`:''}</div></div>${!user&&!preview?'<div class="hint">Registre sus datos. Recibirá un enlace privado para consultar su propuesta; la contraseña se crea después de aprobar el pago.</div>':''}<form id="registration-form">${step===steps[0]?`<div class="fields"><label>Nombre completo<input name="participantName" required maxlength="160" autocomplete="name" value="${esc(enrollmentProfile.name||user?.name)}"></label><label>Correo electrónico<input name="participantEmail" type="email" required autocomplete="email" value="${esc(enrollmentProfile.email||user?.email)}" ${user&&!preview?'readonly':''}></label><label>Identificación<input name="identification" required maxlength="80" value="${esc(enrollmentProfile.identification||user?.identification)}"></label><label>Perfil de participación<select name="participationRole">${roleOptions(enrollmentProfile.role||'attendee')}</select></label></div><div class="section-break"><h3>Información de su propuesta</h3></div>`:''}${visible.filter(q=>q.step===step).map(inputQuestion).join('')||'<p>Este paso no requiere respuestas para tu perfil.</p>'}${step===steps.at(-1)?`<label class="check consent-card"><input id="consent" type="checkbox" required>Autorizo el uso de mis datos para gestionar mi inscripción y enviar las comunicaciones de este evento.</label>`:''}<div class="actions form-actions">${step!==steps[0]?'<button type="button" data-action="previous-step">← Anterior</button>':''}<button class="primary">${step===steps.at(-1)?'Enviar inscripción ↗':'Siguiente sección →'}</button>${preview?'<button type="button" data-action="back-admin">Volver al editor</button>':''}</div></form></section></div></div>`,true)}
function renderAccounts(){shell(heading('Cada rol, su espacio académico.','Las cuentas de jurado se asignan únicamente desde administración.','<button class="primary" data-action="assign-judge">＋ Asignar jurado</button>')+`<div class="account-grid">${accounts.map(a=>`<section class="panel light"><span class="eyebrow">${esc(roles[a.role]||roles.attendee)}</span><h3>${esc(a.name)}</h3><p>${esc(a.email)}</p><small>${a.activated?'Cuenta activada':'Activación pendiente'}</small></section>`).join('')||'<p>Aún no hay cuentas registradas.</p>'}</div>`)}
function renderPosters(){shell(heading('Evaluar para construir conocimiento.','Configure las categorías, asigne jurados y consulte el consolidado.','<button class="primary" data-action="new-poster">＋ Crear póster</button>')+eventSelect()+categoriesMarkup(categories)+'<div class="panel-head"><h2>Pósteres del evento</h2></div>'+postersMarkup(posters,true))}
async function portal(){
 const previousView=view;view='portal';myProfile=await call('myProfile');registrations=await call('myRegistrations');attendance=await call('myAttendance');speakerConferences=await call('mySpeakerConferences');posters=await call('listPosters');
 const cards=[];for(const r of registrations){let ev;try{ev=await call('getEvent',{eventId:r.eventId})}catch{ev={title:'Evento'}};
 if(fullyApproved(r)){const cs=await call('listConferences',{eventId:r.eventId});cards.push(`<div class="panel-head"><h2>${esc(ev.title)}</h2></div>${profileCard(r,speakerConferences.filter(c=>c.speakerRegistrationId===r.id))}<div class="panel-head"><h2>Mi asistencia a conferencias</h2><button data-action="portal">Actualizar</button></div><p>Registre su participación con la imagen y la clave compartida durante cada conferencia.</p><div class="grid">${cs.map(c=>conferenceCard(c,false,r)).join('')||'<p>Aún no hay conferencias publicadas.</p>'}</div>`)}
 else cards.push(`<section class="panel light"><span class="eyebrow">Estado de mi propuesta</span><h2>${esc(ev.title)}</h2><p>${esc(roles[r.role]||roles.attendee)}</p><div class="progress"><i style="width:${r.status==='approved'?60:25}%"></i></div><div class="statusline"><span>Propuesta</span>${badge(r.status)}</div><div class="statusline"><span>Pago</span>${badge(r.payment)}</div><p>${r.status==='pending'?'Hemos recibido su inscripción. El comité organizador revisará su propuesta y le informará los siguientes pasos por correo.':r.status==='rejected'?'Su propuesta no fue aprobada. Puede contactar al equipo organizador para obtener más información.':'Felicitaciones. Su propuesta superó el primer filtro. Complete el pago y espere su validación para activar la cuenta.'}</p>${r.status==='approved'&&r.payment!=='approved'?`<button class="primary" data-pay="${esc(r.id)}">Continuar con el pago ↗</button>`:''}<small>Referencia: ${esc(r.id)}</small></section>`);
 }
 const eligible=myProfile.role==='judge'||registrations.some(fullyApproved);
 const activate=eligible&&!myProfile.activated?'<section class="panel light"><h2>Active su cuenta.</h2><p>Conservamos los datos que registró. Solo necesita crear su contraseña.</p><button class="primary" data-action="activate">Crear contraseña</button></section>':'';
 const judge=myProfile.role==='judge';shell(heading(judge?'Su espacio de evaluación académica.':'Su participación en el encuentro.','Su perfil, sus actividades y los siguientes pasos en un solo lugar.')+activate+(judge?'<section class="panel light"><span class="eyebrow">Jurado asignado</span><h2>'+esc(myProfile.name)+'</h2><p>Complete las evaluaciones de los pósteres que le haya asignado el comité organizador.</p></section>'+postersMarkup(posters,false,true):'')+cards.join('')+(!judge&&!cards.length?'<section class="panel light"><h2>Aún no tiene inscripciones.</h2><p>Abra el enlace público del evento para inscribirse.</p></section>':'')+(!judge&&posters.length?'<h2>Mis pósteres</h2>'+postersMarkup(posters):''),true);if(previousView!=='portal')window.scrollTo({top:0,behavior:'instant'});
}
function authDialog(mode='login'){
 const names={login:'Iniciar sesión',signup:'Crear cuenta',tracking:'Consultar mi propuesta'};
 modal('<h2>Su acceso al encuentro académico.</h2>'+`<div class="auth-tabs">${Object.entries(names).map(([v,n])=>`<button data-auth-mode="${v}" aria-pressed="${v===mode}">${n}</button>`).join('')}</div><form id="auth-form" data-mode="${mode}"><p>${mode==='tracking'?'Le enviaremos un enlace privado para consultar su propuesta. No necesita una contraseña durante la revisión.':mode==='signup'?'Si ya envió su inscripción, use el enlace de activación recibido tras la aprobación del pago. Sus datos se conservan.':'Ingrese con el correo y la contraseña de su cuenta.'}</p><div class="fields">${mode==='signup'?'<label class="wide">Nombre completo<input name="name" required maxlength="160" autocomplete="name"></label>':''}<label class="wide">Correo<input name="email" type="email" required autocomplete="email" value="${esc(enrollmentProfile.email)}"></label>${mode!=='tracking'?'<label class="wide">Contraseña<input name="password" type="password" minlength="8" required autocomplete="'+(mode==='signup'?'new-password':'current-password')+'"></label>':''}</div><button class="primary">${mode==='tracking'?'Enviar enlace privado':'Continuar'}</button>${mode==='login'?'<button type="button" class="subtle" data-action="reset-password">Recuperar contraseña</button>':''}${demo?'<div class="hint">Demostración: las contraseñas no se almacenan ni se validan. El correo admin@example.com abre administración. El acceso de seguimiento simula la verificación del correo.</div>':''}</form>`);
}
function activationDialog(){modal(`<h2>Cree su contraseña.</h2><div class="auth-summary">${esc(myProfile.name||'Sus datos de inscripción se conservan')}<br>${esc(myProfile.email||user?.email)}</div><form id="activation-form"><label>Contraseña<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><label>Confirmar contraseña<input name="confirmation" type="password" required minlength="8" autocomplete="new-password"></label><button class="primary">Activar mi cuenta</button></form>`)}
function stampDialog(cId,rId){modal(`<h2>Confirme su asistencia.</h2><p>Adjunte una imagen como evidencia de su participación. Debe recibirse dentro del horario definido por el equipo organizador.</p><form id="stamp-form" data-conference="${esc(cId)}" data-registration="${esc(rId)}"><label>Clave de la conferencia<input name="code" required maxlength="40" autocomplete="off" placeholder="Clave compartida por el ponente"></label><label class="file">Evidencia · JPG, PNG o WebP · máximo 3 MB<input name="image" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="primary">Subir y sellar asistencia ↗</button></form>`)}
function download(content,name,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function csv(){const keys=[...new Set(registrations.flatMap(r=>Object.keys(r.answers)))];const cell=v=>'"'+String(Array.isArray(v)?v.join(' | '):v??'').replace(/^[\s]*[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[['ID','Nombre','Correo','Inscripción','Pago','Fecha',...keys],...registrations.map(r=>[r.id,r.name,r.email,status[r.status],status[r.payment],r.createdAt,...keys.map(k=>r.answers[k])])].map(row=>row.map(cell).join(',')).join('\r\n'),'inscripciones.csv');}
function attendanceCSV(){const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('\ufeff'+[['ID','Inscripción','Conferencia','Sellado UTC','Certificado','Evidencia Drive ID','Certificado Drive ID'],...attendance.map(a=>[a.id,a.registrationId,a.conferenceId,a.stampedAt,a.certificateStatus,a.evidenceFileId,a.certificateFileId])].map(row=>row.map(cell).join(',')).join('\r\n'),'asistencias.csv');}
async function route(){const query=new URLSearchParams(location.search);if(!demo&&query.get('mode')==='resetPassword'&&query.get('oobCode')){view='activation';shell('<section class="auth panel light"><h2>Active su cuenta académica.</h2><p>Conservamos su información de inscripción. Cree una contraseña para continuar.</p><form id="email-activation-form"><label>Contraseña<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><label>Confirmar contraseña<input name="confirmation" type="password" minlength="8" required autocomplete="new-password"></label><button class="primary">Crear contraseña</button></form></section>',true);return;}if(isEmailAccess()){view='email-access';shell('<section class="auth panel light"><h2>Consulte su propuesta.</h2><p>Confirme el correo al que enviamos este enlace privado.</p><form id="email-access-form"><label>Correo<input name="email" type="email" required autocomplete="email"></label><button class="primary">Consultar mi estado</button></form></section>',true);return;}if(user&&!user.admin&&!demo&&!user.verified){shell('<section class="panel light"><h2>Verifique su correo.</h2><p>Le enviamos un mensaje de verificación. Abra el enlace y vuelva aquí para continuar.</p><button data-action="refresh-user">Ya verifiqué mi correo</button></section>',true);return;}const params=new URLSearchParams(location.hash.slice(1));if(params.has('form')){preview=false;draft=await call('getEvent',{eventId:params.get('form')});answers={};enrollmentProfile={};step=1;view='public';renderPublic()}else if(user?.admin)await adminView('overview');else if(user)await portal();else shell(`<div class="auth panel light"><span class="eyebrow">Bienvenido</span><h2>Tu próximo encuentro empieza aquí.</h2><p>Ingresa a tu cuenta para consultar tus inscripciones o abre el enlace público del evento.</p><button class="primary" data-action="auth">Ingresar o crear cuenta ↗</button></div>`,true)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;setWorking(b,true);try{
 if(b.hasAttribute('data-close'))return close();
 if(b.dataset.authMode)return authDialog(b.dataset.authMode);
 if(b.dataset.category)return modal(categoryDialog(categories.find(c=>c.id===b.dataset.category)));
 if(b.dataset.deleteCategory){modal('<h2>¿Eliminar esta categoría?</h2><p>Dejará de estar disponible para nuevos pósteres. Los pósteres existentes conservarán su rúbrica y evaluaciones.</p><button class="danger" data-confirm-delete-category="'+esc(b.dataset.deleteCategory)+'">Eliminar categoría</button>');return;}
 if(b.dataset.confirmDeleteCategory){await call('deleteCategory',{categoryId:b.dataset.confirmDeleteCategory});close();return await adminView('posters');}
 if(b.dataset.editPoster)return modal(posterDialog(categories,registrations,accounts,posters.find(p=>p.id===b.dataset.editPoster)));
 if(b.dataset.evaluate)return modal(evaluationDialog(posters.find(p=>p.id===b.dataset.evaluate)));
 if(b.dataset.reportPoster){const report=await call('getEvaluationReport',{posterId:b.dataset.reportPoster});modal(reportMarkup(report)+(report.final?'<button data-download-report="'+esc(b.dataset.reportPoster)+'">'+(demo?'Descargar formato de demostración':'Descargar PDF de Drive')+'</button>':'<div class="hint">El formato final se generará cuando todos los jurados asignados envíen su evaluación.</div>'));return;}
 if(b.dataset.downloadReport){if(demo){const report=await call('getEvaluationReport',{posterId:b.dataset.downloadReport});download('<!doctype html><html lang="es"><meta charset="utf-8"><title>Evaluación académica</title><style>body{font:16px Arial;padding:40px;max-width:900px;margin:auto}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ccc;padding:12px;text-align:left}section{margin:30px 0}</style><p>DEMOSTRACIÓN · No almacenado en Drive</p>'+reportMarkup(report)+'</html>','evaluacion-'+report.posterId+'.html','text/html');}else{const f=await call('downloadEvaluationReport',{posterId:b.dataset.downloadReport});download(Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0)),f.fileName,'application/pdf');}return;}
 if(b.dataset.registrationRole){await call('updateRegistration',{registrationId:b.dataset.registrationRole,role:$('#registration-role').value});close();return await adminView('registrations');}
 if(b.dataset.nav){captureDraft();return await adminView(b.dataset.nav)}
 if(b.dataset.edit){draft=structuredClone(events.find(x=>x.id===b.dataset.edit));view='editor';return renderEditor()}
 if(b.dataset.preview){draft=structuredClone(events.find(x=>x.id===b.dataset.preview));preview=true;step=1;answers={};return renderPublic()}
 if(b.dataset.share){const url=new URL(location.href);url.hash='form='+encodeURIComponent(b.dataset.share);modal(`<h2>Comparte el primer paso.</h2><p>Este enlace abre el formulario publicado.</p><label>Enlace público<input id="share-url" readonly value="${esc(url.href)}"></label><button class="primary" data-action="copy-link" style="margin-top:20px">Copiar enlace</button>${demo?'<div class="hint">En demo, el enlace solo encontrará el formulario en este navegador. Al configurar Firebase será público y compartido entre dispositivos.</div>':''}`);return}
 if(b.hasAttribute('data-remove')){captureDraft();const q=draft.questions.splice(Number(b.dataset.remove),1)[0];draft.questions.forEach(p=>{if(p.condition?.field===q.id)delete p.condition});return renderEditor()}
 if(b.hasAttribute('data-move')){captureDraft();const i=Number(b.dataset.move),j=i+Number(b.dataset.dir);[draft.questions[i],draft.questions[j]]=[draft.questions[j],draft.questions[i]];renderEditor();return}
 if(b.hasAttribute('data-filter'))return renderRegistrations(b.dataset.filter,$('#search')?.value||'');
 if(b.dataset.review){await call('updateRegistration',{registrationId:b.dataset.review,status:b.dataset.status});await adminView('registrations');notice('Estado actualizado.');return}
 if(b.dataset.payment){modal(`<h2>Validar pago</h2><p>Confirma el pago únicamente después de verificarlo en tu módulo o con el soporte correspondiente.</p><form id="payment-form" data-id="${esc(b.dataset.payment)}"><label>Referencia verificable del pago<input name="reference" required maxlength="200"></label><button class="primary" style="margin-top:20px">Aprobar pago verificado</button></form>`);return}
 if(b.dataset.detail){const r=registrations.find(r=>r.id===b.dataset.detail);modal(`<h2>${esc(r.name)}</h2><p>${esc(r.email)}</p><label>Perfil de participación<select id="registration-role">${roleOptions(r.role)}</select></label><button data-registration-role="${esc(r.id)}">Actualizar perfil</button><dl>${Object.entries(r.answers).map(([k,v])=>`<dt class="eyebrow" style="margin-top:20px">${esc(events.find(e=>e.id===r.eventId)?.questions.find(q=>q.id===k)?.label||k)}</dt><dd style="margin-left:0">${esc(Array.isArray(v)?v.join(', '):v)}</dd>`).join('')}</dl>`);return}
 if(b.dataset.conference)return conferenceDialog(conferences.find(c=>c.id===b.dataset.conference));
 if(b.dataset.stamp)return stampDialog(b.dataset.stamp,b.dataset.registration);
 if(b.dataset.pay){const result=await call('getPaymentLink',{registrationId:b.dataset.pay});const u=new URL(result.url);if(u.protocol!=='https:')throw new Error('URL de pago inválida.');location.assign(u.href);return}
 if(b.dataset.certificate){const f=await call('getCertificate',{attendanceId:b.dataset.certificate});download(Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0)),f.fileName,'application/pdf');return}
 if(b.dataset.retry){await call('retryJob',{jobId:b.dataset.retry});return await adminView('reports')}
 switch(b.dataset.action){
 case 'refresh-user':user=await currentUser();return await route();
 case 'new-category':if(!selected)throw Error('Cree un evento primero.');return modal(categoryDialog());
 case 'new-poster':if(!selected)throw Error('Cree un evento primero.');return modal(posterDialog(categories,registrations,accounts));
 case 'assign-judge':return modal('<h2>Asignar cuenta de jurado</h2><p>Se enviará una invitación para crear la contraseña. El jurado verá únicamente sus pósteres asignados.</p><form id="judge-form"><label>Nombre completo<input name="name" required maxlength="160"></label><label>Correo<input name="email" type="email" required></label><button class="primary">Asignar e invitar</button></form>');
 case 'activate':return activationDialog();
 case 'flip-card':{const card=b.closest('.identity-card'),front=$('.identity-front',card),back=$('.identity-back',card);front.hidden=!front.hidden;back.hidden=!back.hidden;$('button',front.hidden?back:front).focus();return;}
 case 'admin-home':location.hash='';return await adminView('overview');case 'new-form':return newForm();case 'save-form':case 'publish-form':b.disabled=true;return await saveForm(b.dataset.action==='publish-form');
 case 'preview-registration-success':return celebrate('registration',{preview:true});case 'preview-attendance-success':return celebrate('attendance',{preview:true});
 case 'remove-cover':captureDraft();draft.appearance={...draft.appearance,image:'',cover:'orbital'};return renderEditor();
 case 'add-section':{captureDraft();const next=Math.max(...draft.questions.map(q=>q.step))+1;if(next>10)return notice('Puedes crear hasta diez secciones.');draft.sections=sectionsFor(draft);draft.sections.push({step:next,title:'Nueva sección',description:''});draft.questions.push({id:crypto.randomUUID(),label:'Pregunta de la nueva sección',type:'text',required:false,step:next});return renderEditor()}
 case 'add-question':captureDraft();draft.questions.push({id:crypto.randomUUID(),label:'Pregunta sin título',type:'text',required:false,step:draft.questions.at(-1)?.step||1});return renderEditor();
 case 'preview-draft':captureDraft();preview=true;answers={};step=1;return renderPublic();
 case 'back-admin':preview=false;view='editor';return renderEditor();case 'previous-step':{const ss=[...new Set(draft.questions.map(q=>q.step))].sort((a,b)=>a-b);step=ss[ss.indexOf(step)-1];return renderPublic()}
 case 'auth':return authDialog();case 'reset-password':{const email=$('[name=email]',$('#auth-form')).value;if(!email)throw new Error('Escribe tu correo.');await resetPassword(email);notice('Si la cuenta existe, recibirás instrucciones de recuperación.');return}
 case 'logout':await logout();user=null;return await route();case 'role':{accounts=user?await call(user.admin?'listAccounts':'myProfile'):[];if(!Array.isArray(accounts))accounts=[accounts];modal('<h2>Explorar la demostración</h2><p>Seleccione una cuenta. Este cambio de rol solo está disponible en la demostración.</p><form id="demo-role-form"><label>Cuenta<select name="email"><option>admin@example.com</option>'+accounts.filter(a=>a.email!=='admin@example.com').map(a=>'<option value="'+esc(a.email)+'">'+esc(a.name)+' · '+esc(roles[a.role]||roles.attendee)+' · '+esc(a.email)+'</option>').join('')+'</select></label><button class="primary">Abrir espacio</button></form>');return;}case 'reset':return resetDemo();
 case 'portal':if(!user)return authDialog();return await portal();case 'new-conference':return conferenceDialog();case 'export':return csv();case 'export-attendance':return attendanceCSV();case 'copy-link':await navigator.clipboard.writeText($('#share-url').value);notice('Enlace copiado.');return;
 }
 }catch(err){notice(err.message)}finally{setWorking(b,false);if(b.isConnected)b.disabled=false}});
document.addEventListener('change',async e=>{try{const t=e.target;
 if(['participantName','participantEmail','identification','participationRole'].includes(t.name))enrollmentProfile[{participantName:'name',participantEmail:'email',identification:'identification',participationRole:'role'}[t.name]]=t.value;
 if(t.id==='form-image'){captureDraft();coverUploading=true;try{const image=await prepareCover(t.files[0]);draft.appearance={...draft.appearance,image,cover:'image'};renderEditor();notice('La imagen de portada está lista. Guarde o publique el formulario para conservarla.')}finally{coverUploading=false}return}
 if(t.name==='form-theme'||t.id==='form-layout'||t.id==='form-cover'){captureDraft();$('.design-preview').dataset.theme=draft.appearance.theme;return}
 if(t.id==='event-select'){selected=t.value;await adminView(view);return}
 if(t.dataset.q){captureDraft();const q=draft.questions.find(q=>q.id===t.closest('[data-question]').dataset.question),key=t.dataset.q;
 if(key==='conditionField'){if(t.value)q.condition={field:t.value,operator:'eq',value:''};else delete q.condition;renderEditor()}
 else if(key==='conditionOperator')q.condition.operator=t.value;else if(key==='conditionValue')q.condition.value=t.value;
 else if(key==='required')q.required=t.checked;else if(key==='step')q.step=Number(t.value);else if(key==='options')q.options=t.value.split('\n').map(s=>s.trim()).filter(Boolean);
 else{q[key]=t.value;if(key==='type'){if(['radio','checkbox','select'].includes(q.type))q.options=q.options||['Opción 1','Opción 2'];renderEditor()}}
 }
 }catch(err){notice(err.message)}});
document.addEventListener('input',e=>{const t=e.target;if(['participantName','participantEmail','identification','participationRole'].includes(t.name))enrollmentProfile[{participantName:'name',participantEmail:'email',identification:'identification',participationRole:'role'}[t.name]]=t.value;if(t.dataset.q==='label'){const q=draft.questions.find(q=>q.id===t.closest('[data-question]').dataset.question);q.label=t.value}if(!t.dataset.answer)return;const id=t.dataset.answer,q=draft.questions.find(q=>q.id===id);if(q.type==='checkbox')answers[id]=[...document.querySelectorAll('[data-answer]')].filter(x=>x.dataset.answer===id&&x.checked).map(x=>x.value);else answers[id]=t.value;
 if(draft.questions.some(x=>x.condition?.field===id)){const pos=t.selectionStart;renderPublic();const target=[...document.querySelectorAll('[data-answer]')].find(x=>x.dataset.answer===id&&(q.type!=='radio'||x.value===t.value));target?.focus();try{target?.setSelectionRange(pos,pos)}catch{}}
});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=$('button[type=submit],button.primary',f);if(b){b.disabled=true;setWorking(b,true)}try{
 if(f.id==='auth-form'){const d=new FormData(f);if(f.dataset.mode==='tracking'){await call('requestAccess',{email:d.get('email')});if(demo){user=await completeEmailAccess(d.get('email'));close();location.hash='';await portal();}else{close();notice('Si este correo tiene una inscripción, recibirá un enlace privado.');}return;}user=await login(d.get('email'),d.get('password'),f.dataset.mode==='signup',d.get('name'));close();if(view==='public')renderPublic();else await route();return}
 if(f.id==='demo-role-form'){user=await login(new FormData(f).get('email'),'demo');close();location.hash='';await route();return;}
 if(f.id==='email-access-form'){user=await completeEmailAccess(new FormData(f).get('email'));history.replaceState(null,'',location.pathname);await route();return;}
 if(f.id==='activation-form'||f.id==='email-activation-form'){const d=new FormData(f);if(d.get('password')!==d.get('confirmation'))throw Error('Las contraseñas deben coincidir.');if(f.id==='email-activation-form'){user=await completeActivation(new URLSearchParams(location.search).get('oobCode'),d.get('password'));history.replaceState(null,'',location.pathname);}else{user=await setAccountPassword(d.get('password'));close();}await portal();notice('Su cuenta está activada. Bienvenido al encuentro académico.');return;}
 if(f.id==='judge-form'){await call('assignJudge',Object.fromEntries(new FormData(f)));close();await adminView('accounts');notice(demo?'Invitación simulada. Puede explorar esta cuenta desde Cambiar rol.':'Cuenta asignada. La invitación se enviará por correo.');return;}
 if(f.id==='category-form'){const d=new FormData(f),old=categories.find(c=>c.id===f.dataset.id);const criteria=d.get('criteria').split('\n').filter(l=>l.trim()).map((line,i)=>{const [label,weight,...rest]=line.split('|');if(rest.length)throw Error('Use una sola barra | por criterio.');return {id:old?.criteria[i]?.id||crypto.randomUUID(),label:label.trim(),weight:Number(weight)};});await call('saveCategory',{category:{id:f.dataset.id,eventId:selected,name:d.get('name'),criteria}});close();return await adminView('posters');}
 if(f.id==='poster-form'){const d=new FormData(f);await call('savePoster',{poster:{...Object.fromEntries(d),id:f.dataset.id,eventId:selected,judgeIds:d.getAll('judgeIds')}});close();return await adminView('posters');}
 if(f.id==='evaluation-form'){const d=new FormData(f),p=posters.find(p=>p.id===f.dataset.id),scores=Object.fromEntries(p.rubric.criteria.map(q=>[q.id,Number(d.get('score_'+q.id))]));await call('submitEvaluation',{posterId:p.id,scores,comments:d.get('comments')});close();await portal();notice('Su evaluación fue recibida correctamente. Gracias por su aporte académico.');return;}
 if(f.id==='registration-form'){const data=new FormData(f);if(data.has('participantName'))enrollmentProfile={name:data.get('participantName'),email:data.get('participantEmail'),identification:data.get('identification'),role:data.get('participationRole')};const ss=[...new Set(draft.questions.map(q=>q.step))].sort((a,b)=>a-b);validateAnswers(draft.questions.filter(q=>q.step<=step),answers);if(step!==ss.at(-1)){step=ss[ss.indexOf(step)+1];return renderPublic()}if(preview){celebrate('registration',{preview:true});return}if(!user){await call('registerGuest',{eventId:draft.id,answers,consent:true,profile:enrollmentProfile});if(demo){user=await completeEmailAccess(enrollmentProfile.email);location.hash='';await portal();}else{shell('<section class="panel light"><h2>Su propuesta está en revisión.</h2><p>Enviamos a su correo las instrucciones y el enlace privado para consultar el estado.</p><button data-auth-mode="tracking">Consultar mi propuesta</button></section>',true);}}else{await call('register',{eventId:draft.id,answers,consent:true,profile:enrollmentProfile});location.hash='';await portal();}celebrate('registration',{demo});return}
 if(f.id==='conference-form'){const d=new FormData(f);await call('saveConference',{conference:{id:f.dataset.id,eventId:selected,title:d.get('title'),speaker:d.get('speaker'),speakerRegistrationId:d.get('speakerRegistrationId'),location:d.get('location'),opensAt:new Date(d.get('opensAt')+'-05:00').toISOString(),closesAt:new Date(d.get('closesAt')+'-05:00').toISOString(),active:d.has('active')}});close();return await adminView('conferences')}
 if(f.id==='payment-form'){await call('updateRegistration',{registrationId:f.dataset.id,payment:'approved',reference:new FormData(f).get('reference')});close();await adminView('registrations');notice('Pago verificado. Se preparó el correo para activar la cuenta.');return}
 if(f.id==='settings-form'){await call('updateSettings',{settings:Object.fromEntries(new FormData(f))});notice('Configuración guardada.');return}
 if(f.id==='stamp-form'){const file=f.image.files[0];if(file.size>3*1024*1024)throw new Error('La imagen debe pesar como máximo 3 MB.');const base64=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result.split(',')[1]);fr.onerror=reject;fr.readAsDataURL(file)});await call('stamp',{registrationId:f.dataset.registration,conferenceId:f.dataset.conference,code:new FormData(f).get('code'),base64,mime:file.type,fileName:file.name});close();await portal();celebrate('attendance',{demo});return}
 }catch(err){notice(err.message)}finally{if(b){setWorking(b,false);if(b.isConnected)b.disabled=false}}});
window.addEventListener('hashchange',()=>route().catch(e=>notice(e.message)));
try{user=await init();await route()}catch(e){shell(`<section class="panel light"><h1>Configuración pendiente.</h1><p>${esc(e.message)}</p><p>Consulta la guía de instalación incluida con la aplicación.</p></section>`,true)}
